// Opening a project: cinema settings and workshop packs first (they stay applied even if the file is rejected), then the project data, then imported-model registrations.
async function restoreProject(data,portable=false){CINEMA={...CINEMA_DEFAULTS,...data.cinema};
 const packs=(data.workshop?.packs||[]).map(validateExtensionPack);workshopPacks=[];workshopGLBs.clear();workshopExtensions.clear();installExtensionPack(octopusPack(),false);for(const p of packs)installExtensionPack(p,true);await restoreProjectData(data,portable);
 for(const reg of data.workshop?.registrations||[]){const source=importedModels.find(x=>x.userData.assetId===reg.sourceModelId);if(source)registerImportedAsset(source,reg)}rebuildCatalog();if($('storyIdea')){$('storyIdea').value=data.workshop?.idea||'';$('storyNeeds').value=data.workshop?.needs||''}refreshImportChoices();
syncCinemaUI()}

