function renderCatalogList(){const q=$('assetSearch').value.trim().toLowerCase(),cat=$('catalogCategory').value,baseOnly=$('catalogBaseOnly').checked,list=catalogEntries.filter(e=>(cat==='all'||e.category===cat)&&(!baseOnly||e.variant===0)&&(e.name+' '+e.id+' '+e.archetype).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(list.length/30));catalogPage=cl(catalogPage,0,pages-1);const root=$('assetList');root.replaceChildren();for(const e of list.slice(catalogPage*30,catalogPage*30+30)){const b=document.createElement('button');b.className='asset-item'+(catalogSelection===e.id&&catalogPreviewMode?' active':'');const icon=document.createElement('span');icon.className='asset-icon';icon.textContent={human:'♙',vehicle:'▰',boat:'≈',aircraft:'✈',building:'▥',tree:'♧',plant:'♧',animal:'◇',food:'◉',trash:'▧',debris:'✧',prop:'□',environment:'☀'}[e.category]||'⬡';const text=document.createElement('span'),name=document.createElement('span'),meta=document.createElement('small');text.style.minWidth=0;name.className='name';name.textContent=e.name;meta.textContent=e.id;text.append(name,meta);b.append(icon,text);b.onclick=()=>selectCatalog(e.id);root.append(b)}$('assetPage').textContent=list.length.toLocaleString()+' presets · '+(catalogPage+1)+' / '+pages;$('prevAssets').disabled=catalogPage===0;$('nextAssets').disabled=catalogPage>=pages-1;$('catalogStats').textContent=CATALOG_BASE.length+' authored archetypes · '+catalogEntries.length.toLocaleString()+' procedural presets';}
