function syncCatalogInspector(){const a=currentAsset(),id=a?.object.userData.catalogId,ref=resolveCatalog(id);$('catalogTools').hidden=!ref;$('useClip').disabled=!!a?.catalog||(!ref&&a?.category!=='imported');$('useClip').textContent=ref?'Apply state to film':'Use selected clip in film';$('modelFields').disabled=!!a?.catalog;$('modelFields').hidden=!!a?.catalog;$('applyMaterial').disabled=!!a?.catalog;$('resetMaterial').disabled=!!a?.catalog;if(!ref)return;$('catalogID').textContent=ref.entry.id;$('catalogCapabilities').textContent=ref.base.rig+' · '+ref.base.states.length+' states'+(ref.base.expressions.length?' · '+ref.base.expressions.length+' expressions':'');$('catalogAdd').hidden=!a.catalog;$('removeCatalogInstance').hidden=!!a.catalog||!a.object.userData.instanceId;$('exportCatalogGlb').disabled=recording;$('expression').replaceChildren(...(ref.base.expressions.length?ref.base.expressions:['neutral']).map(x=>new Option(x,x)));$('expression').disabled=!ref.base.expressions.length;const inst=catalogInstances.find(x=>x.object===a.object);$('expression').value=inst?.spec.expression||'neutral';$('catalogShader').value=inst?.spec.shader||'standard';const acc=$('accessoryChecks');acc.replaceChildren();for(const name of ref.base.accessories){const label=document.createElement('label'),input=document.createElement('input');label.className='check';input.type='checkbox';input.value=name;input.checked=assetObject?.getObjectByName('Accessory_'+name)?.visible||false;input.onchange=()=>{setCatalogAccessories(assetObject,selectedAccessories())};label.append(input,document.createTextNode(name));acc.append(label)}$('applyCatalogState').disabled=!!a.catalog;}
function selectedAccessories(){return [...$('accessoryChecks').querySelectorAll('input:checked')].map(x=>x.value)}
function addCatalogToScene(){if(recording||seeking)return;try{const j=parse(),id=catalogSelection;if(!resolveCatalog(id))return;j.schema_version=7;j.assets=j.assets||[];const prefix=resolveCatalog(id).base.id.replace('.','_');let n=1;while(j.assets.some(x=>x.instance_id===prefix+'_'+n))n++;const instance_id=prefix+'_'+n;const spec={instance_id,asset_id:id,position:[0,0,0],rotation:[0,0,0],scale:[1,1,1],state:$('assetAnimation').value==='rest'?'idle':$('assetAnimation').value,shader:$('catalogShader').value};if(resolveCatalog(id).base.kind==='human'){spec.expression=$('expression').value;spec.accessories=selectedAccessories()}j.assets.push(spec);$('ta').value=JSON.stringify(j,null,2);catalogPreviewMode=false;if(validateOnly()){selectAsset('instance:'+instance_id,true);notifyUser('Added '+instance_id+'. Use XYZ offsets to place it.')}}catch(e){notifyUser(e.message)}}
