function normalizePack(pack){if(!pack||pack.format!=='frame-asset-pack'||pack.version!==1||typeof pack.id!=='string'||!Array.isArray(pack.assets)||pack.assets.length>10000)throw Error('Invalid frame asset pack.');const ids=new Set();const clean=[];for(const raw of pack.assets){if(!raw||typeof raw.id!=='string'||!/^[a-z][a-z0-9_.-]{2,95}$/.test(raw.id)||ids.has(raw.id))throw Error('Invalid/duplicate preset ID in pack.');ids.add(raw.id);const base=CATALOG_BASE.find(b=>b.id===raw.archetype);if(!base)throw Error('Unknown archetype '+raw.archetype);if(!Number.isInteger(raw.variant)||raw.variant<0||raw.variant>23||typeof raw.name!=='string'||raw.name.length>140||!/^#[a-f0-9]{6}$/i.test(raw.color)||!Number.isInteger(raw.seed)||raw.seed<1||raw.seed>2147483646||![0,1,2].includes(raw.wear)||!Number.isFinite(raw.proportion)||raw.proportion<.5||raw.proportion>2||!Array.isArray(raw.accessories)||raw.accessories.some(x=>!base.accessories.includes(x)))throw Error('Invalid recipe: '+raw.id);const e={id:raw.id,archetype:base.id,name:raw.name,category:base.category,seed:raw.seed,variant:raw.variant,color:raw.color,wear:raw.wear,proportion:raw.proportion,accessories:raw.accessories,states:base.states,rig:base.rig};const existing=catalogById.get(e.id);if(existing){if(JSON.stringify(existing)!==JSON.stringify(e))throw Error('Pack conflicts with existing asset '+e.id);continue}clean.push(e)}return{id:pack.id,name:String(pack.name||pack.id).slice(0,100),format:'frame-asset-pack',version:1,assets:clean}}
